import{_ as t,c as a,o as i,ag as o}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/philips-slide.webp",f=JSON.parse('{"title":"Philips TIFF Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Philips TIFF whole-slide images in your browser, from your disk or a link, with label and macro. Free, nothing to install.","frontmatter":{"title":"Philips TIFF Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Philips TIFF whole-slide images in your browser, from your disk or a link, with label and macro. Free, nothing to install."},"headers":[],"relativePath":"guides/philips-tiff.md","filePath":"guides/philips-tiff.md"}'),r={name:"guides/philips-tiff.md"};function n(l,e,h,d,p,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="philips-tiff-slides-in-the-browser" tabindex="-1">Philips TIFF Slides in the Browser <a class="header-anchor" href="#philips-tiff-slides-in-the-browser" aria-label="Permalink to &quot;Philips TIFF Slides in the Browser&quot;">​</a></h1><p>Open the TIFF slides your Philips scanner saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p><img src="'+s+'" alt="Philips-1.tiff open in the viewer"></p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells.</li><li><strong>Label and Macro.</strong> They appear under the slide&#39;s name. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Empty areas.</strong> Areas the scanner skipped show as white.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Pixel size and magnification.</strong> The pixel size comes from the slide, so measurements read in µm. Philips TIFF states no magnification. Enter it in <a href="./calibration.html">Pixel Size and Magnification</a> and the zoom bar shows it.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Another compression</td><td>This Philips TIFF uses a compression the viewer cannot read yet.</td></tr><tr><td>Not 8-bit RGB</td><td>This Philips TIFF is not 8-bit RGB. The viewer cannot read it yet.</td></tr><tr><td>Another kind of TIFF</td><td>The viewer reads Philips slides among TIFF files. This one is another kind.</td></tr><tr><td>A damaged or incomplete file</td><td>This Philips TIFF looks damaged or incomplete.</td></tr></tbody></table><p>Some Philips files keep the label inside their metadata. Those labels are not shown yet.</p><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Philips-TIFF/" target="_blank" rel="noreferrer">Philips TIFF folder</a>. Download a slide, then drop it on the viewer. They are CC0.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Philips-1.tiff</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;Philips TIFF file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',24)])])}const u=t(r,[["render",n]]);export{f as __pageData,u as default};
